export const makeSiteT = (lang) => (key, vars) => {
  const table = messages[lang] ?? messages.en;
  let text = table[key] ?? key;
  if (vars) text = text.replace(/\{(\w+)\}/g, (_, name) => vars[name] ?? '');
  return text;
};
